parameters.jsCode:
const priority = $('Analyse Assistent').first().json.output.prioritaet_bezeichnung;

const label = $input.all().find(
  item => item.json.name === priority
);

if (!label) {
  throw new Error(`Gmail Label "${priority}" nicht gefunden`);
}

return [{
  json: {
    labelId: label.json.id,
    labelName: label.json.name
  },
  pairedItem: { item: 0 }
}];
